# ---------- 落盘与自验 ----------
ids = B07 + B08
assert len(CASES) == 40, len(CASES)
assert [c["case_id"] for c in CASES] == ids, "id 集或顺序不合批次表"
for c in CASES:
    (OUT / f"{c['case_id']}.json").write_text(json.dumps(c, ensure_ascii=False, indent=1), encoding="utf-8")
# 逐件精确打开自验（只验本批自写件）
ok = 0
cnt = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in ids:
    d = json.loads((OUT / f"{cid}.json").read_text(encoding="utf-8"))
    assert d["case_id"] == cid and d["prediction_text"] and d["basis"] and 0 <= d["confidence"] <= 1
    t = d["trigger"]
    assert set(t) == {"changed_main", "reserve_used", "disputed", "reason"}
    for k in cnt:
        cnt[k] += bool(t[k])
    ok += 1
print(f"WROTE {ok}/40 trigger计数 changed_main={cnt['changed_main']} reserve_used={cnt['reserve_used']} disputed={cnt['disputed']}")
